import base64

# O HTML completo foi codificado em base64 para evitar problemas com caracteres especiais no PowerShell
html_b64 = """

"""

html_content = base64.b64decode(html_b64).decode("utf-8")
path = "pc_frontend/analise_comparativo_receitas.html"
with open(path, "w", encoding="utf-8") as f:
    f.write(html_content)
print("✅ Arquivo HTML completamente reconstruído e limpo!")
